+    gsmtap_hdr_bytes[GSMTAP_HDR_VERSION]  = 0x02;
+    gsmtap_hdr_bytes[GSMTAP_HDR_HDR_LEN]  = 0x04;
+    gsmtap_hdr_bytes[GSMTAP_HDR_TYPE]     = GSMTAP_TYPE_LTE_NAS;
